//! Interned CSS property-name atoms.
//!
//! Every declaration used to heap-allocate its property name (one `String`
//! per parsed declaration, plus a second for the ASCII-lowercasing copy),
//! and the cascade resolved each candidate declaration's name to a
//! property index with a process-wide string-hash lookup per candidate
//! per styled element. This module interns the well-known property names
//! into a single immutable, lock-free table (generated by `build.rs` from
//! the `computed_props!` list in `cascade.rs`, so the two can never drift
//! apart): a well-known name is a `Copy` 1-byte [`PropertyAtom`] (its
//! index in [`PROPS`]), so hot-path compares are one `u8` comparison with
//! no allocation, no hashing, and no synchronization. For the leading
//! computed-property run the atom index doubles as the `props::*` slot
//! index, so the cascade reads the slot straight from the atom.
//!
//! Names outside the table (custom properties `--*`, unknown properties)
//! are not lost: [`PropertyName`] is a two-tier type — a well-known atom
//! plus an optional heap sidecar that carries the original string exactly
//! when the atom is [`PropertyAtom::UNKNOWN`]. Equality stays exact: equal
//! atoms imply equal strings (the table holds unique strings, and
//! interning is deterministic), and two unknown names fall back to
//! comparing their sidecars.
//!
//! Case handling is the caller's job, matching CSS semantics: the parser
//! ASCII-lowercases non-custom property names before interning (see
//! [`PropertyName::intern_lowered_owned`]), and custom property names are
//! case-sensitive, so they intern verbatim.

use std::fmt;
use std::ops::Deref;

include!(concat!(env!("OUT_DIR"), "/props_atom.rs"));

/// A CSS property name: a well-known [`PropertyAtom`] plus, for names
/// outside the atom table (custom properties `--*`, unknown properties),
/// the original string on a heap sidecar.
///
/// `Clone` is cheap for well-known names (one byte copied); unknown names
/// clone their sidecar, exactly like the `String` this type replaces.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PropertyName {
    atom: PropertyAtom,
    /// The original string iff `atom == PropertyAtom::UNKNOWN`.
    spill: Option<Box<str>>,
}

impl Default for PropertyName {
    /// Placeholder with no heap use: the [`PropertyAtom::UNKNOWN`] atom
    /// and no sidecar. Only meaningful as a [`std::mem::take`]/`replace`
    /// target — [`as_str`](PropertyName::as_str) on a default name
    /// panics, exactly like [`PropertyAtom::UNKNOWN`]'s
    /// [`as_str`](PropertyAtom::as_str).
    fn default() -> Self {
        PropertyName {
            atom: PropertyAtom::UNKNOWN,
            spill: None,
        }
    }
}

impl PropertyName {
    /// Intern a borrowed name: well-known names become pure atoms (no
    /// allocation); anything else is copied onto the heap sidecar.
    pub fn intern(name: &str) -> Self {
        match PropertyAtom::lookup(name) {
            Some(atom) => PropertyName { atom, spill: None },
            None => PropertyName {
                atom: PropertyAtom::UNKNOWN,
                spill: Some(name.into()),
            },
        }
    }

    /// Intern, ASCII-lowercasing first when the name needs it. Skips the
    /// intermediate `String` when the name is already lowercase.
    pub fn intern_lowered(name: &str) -> Self {
        if name.as_bytes().iter().all(|b| !b.is_ascii_uppercase()) {
            return Self::intern(name);
        }
        Self::from(name.to_ascii_lowercase())
    }

    /// Intern an owned name, ASCII-lowercasing in place when the name
    /// needs it. This is the parse fast path: an already-lowercase name
    /// costs no allocation at all (well-known names keep just the atom;
    /// unknown names move the `String` into the sidecar), and an
    /// uppercase name is lowered in place rather than copied.
    pub fn intern_lowered_owned(mut name: String) -> Self {
        if name.as_bytes().iter().any(|b| b.is_ascii_uppercase()) {
            name.make_ascii_lowercase();
        }
        Self::from(name)
    }

    /// The atom for this name, or [`PropertyAtom::UNKNOWN`]. Comparing
    /// atoms is exactly string equality: interning is deterministic and
    /// the table holds unique strings.
    pub fn atom(&self) -> PropertyAtom {
        self.atom
    }

    /// The original string.
    pub fn as_str(&self) -> &str {
        match &self.spill {
            Some(s) => s,
            None => self.atom.as_str(),
        }
    }

    /// Whether this is a custom property (`--*`): case-sensitive and
    /// never a well-known atom.
    pub fn is_custom_property(&self) -> bool {
        self.as_str().starts_with("--")
    }
}

impl From<&str> for PropertyName {
    fn from(s: &str) -> Self {
        Self::intern(s)
    }
}

impl From<&String> for PropertyName {
    fn from(s: &String) -> Self {
        Self::intern(s.as_str())
    }
}

impl From<String> for PropertyName {
    /// Zero-copy for unknown names (the `String` becomes the sidecar);
    /// well-known names drop the `String` and keep just the atom.
    fn from(s: String) -> Self {
        match PropertyAtom::lookup(&s) {
            Some(atom) => PropertyName { atom, spill: None },
            None => PropertyName {
                atom: PropertyAtom::UNKNOWN,
                spill: Some(s.into_boxed_str()),
            },
        }
    }
}

impl Deref for PropertyName {
    type Target = str;
    fn deref(&self) -> &str {
        self.as_str()
    }
}

impl AsRef<str> for PropertyName {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

impl fmt::Display for PropertyName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl PartialEq<str> for PropertyName {
    fn eq(&self, other: &str) -> bool {
        self.as_str() == other
    }
}

impl PartialEq<&str> for PropertyName {
    fn eq(&self, other: &&str) -> bool {
        self.as_str() == *other
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_well_known_property_round_trips() {
        // Pins each generated `lookup` arm's index to the table order,
        // and each arm's string back to its atom.
        assert!(!PROPS.is_empty());
        assert!(PROPS.len() < u8::MAX as usize);
        for (i, name) in PROPS.iter().enumerate() {
            let atom =
                PropertyAtom::lookup(name).unwrap_or_else(|| panic!("no lookup arm for {name}"));
            assert_eq!(atom, PropertyAtom(i as u8));
            assert_eq!(atom.as_str(), *name);
        }
        assert_eq!(PropertyAtom::lookup("not-a-property"), None);
        assert_eq!(PropertyAtom::lookup("--custom"), None);
        assert_eq!(PropertyAtom::lookup("COLOR"), None);
    }

    #[test]
    fn computed_atoms_match_props_indices() {
        // The leading table run must stay in `computed_props!`
        // declaration order so an atom index doubles as the `props::*`
        // property index. This pins the generator's parse of cascade.rs
        // against the real table.
        use crate::cascade::COMPUTED_PROPS;
        assert_eq!(COMPUTED_ATOM_COUNT, COMPUTED_PROPS.len());
        assert_eq!(&PROPS[..COMPUTED_ATOM_COUNT], COMPUTED_PROPS);
        for i in 0..COMPUTED_ATOM_COUNT {
            let atom = PropertyAtom(i as u8);
            assert!(atom.is_computed());
            assert_eq!(atom.index() as usize, i);
            assert_eq!(PropertyAtom::lookup(atom.as_str()), Some(atom));
        }
        assert!(!PropertyAtom(COMPUTED_ATOM_COUNT as u8).is_computed());
        // Spot-check the well-known consts land on the right names.
        assert_eq!(PropertyAtom::COLOR.as_str(), "color");
        assert_eq!(PropertyAtom::MARGIN.as_str(), "margin");
        assert_eq!(PropertyAtom::FONT.as_str(), "font");
        assert_eq!(PropertyAtom::BORDER.as_str(), "border");
        assert_eq!(PropertyAtom::BACKGROUND.as_str(), "background");
    }

    #[test]
    fn property_name_interning() {
        let n = PropertyName::intern("color");
        assert_eq!(n.atom(), PropertyAtom::COLOR);
        assert_eq!(n.as_str(), "color");
        assert!(!n.is_custom_property());

        let n = PropertyName::intern_lowered("COLOR");
        assert_eq!(n.atom(), PropertyAtom::COLOR);
        assert_eq!(n.as_str(), "color");

        let n = PropertyName::intern_lowered_owned("Margin-Top".to_string());
        assert_eq!(n.as_str(), "margin-top");

        // Custom properties keep their case on the sidecar.
        let n = PropertyName::from("--MyVar".to_string());
        assert_eq!(n.atom(), PropertyAtom::UNKNOWN);
        assert_eq!(n.as_str(), "--MyVar");
        assert!(n.is_custom_property());

        // Unknown non-custom names ride the sidecar too.
        let n = PropertyName::intern("not-a-real-property");
        assert_eq!(n.atom(), PropertyAtom::UNKNOWN);
        assert_eq!(n.as_str(), "not-a-real-property");
        assert_eq!(n, PropertyName::intern("not-a-real-property"));
        assert_ne!(n, PropertyName::intern("color"));
    }
}
